create or replace function public.account_is_active(uid uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles p where p.id=uid and coalesce(p.account_state,'active')='active' and p.is_active); $$;
revoke all on function public.account_is_active(uuid) from public, anon;
grant execute on function public.account_is_active(uuid) to authenticated, service_role;

create or replace function public.set_my_interests(p_interest_ids bigint[]) returns void language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); cnt int; begin if uid is null then raise exception 'not authenticated'; end if; if not public.account_is_active(uid) then raise exception 'account_restricted'; end if; select count(*) into cnt from unnest(coalesce(p_interest_ids,'{}'::bigint[])) x; if cnt>10 then raise exception 'maximum 10 interests'; end if; if exists(select 1 from unnest(coalesce(p_interest_ids,'{}'::bigint[])) x left join public.interests i on i.id=x where i.id is null or not i.is_active) then raise exception 'invalid interest'; end if; delete from public.user_interests where user_id=uid; insert into public.user_interests(user_id,interest_id) select uid,x from unnest(coalesce(p_interest_ids,'{}'::bigint[])) x on conflict do nothing; end $$;

create or replace function public.set_my_location(lat double precision, lon double precision, p_city text, p_zone text default null) returns void language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); pt geography; tj geography:=st_setsrid(st_makepoint(-117.0382,32.5149),4326)::geography; sd geography:=st_setsrid(st_makepoint(-117.1611,32.7157),4326)::geography; d_tj double precision; d_sd double precision; resolved_city text; begin if uid is null then raise exception 'not authenticated'; end if; if not public.account_is_active(uid) then raise exception 'account_restricted'; end if; if lat < -90 or lat > 90 or lon < -180 or lon > 180 then raise exception 'invalid coordinates'; end if; pt:=st_setsrid(st_makepoint(lon,lat),4326)::geography; d_tj:=st_distance(pt,tj); d_sd:=st_distance(pt,sd); if least(d_tj,d_sd)>100000 then raise exception 'outside_service_area'; end if; resolved_city:=case when d_tj<=d_sd then 'Tijuana' else 'San Diego' end; insert into public.locations(user_id,city,zone,point,privacy_radius_m,updated_at) values(uid,resolved_city,nullif(left(trim(coalesce(p_zone,'')),80),''),pt,1000,now()) on conflict(user_id) do update set city=excluded.city,zone=excluded.zone,point=excluded.point,privacy_radius_m=1000,updated_at=now(); end $$;

create or replace function public.register_my_profile_photo(p_storage_path text) returns uuid language plpgsql security definer set search_path=public,storage as $$ declare uid uuid:=auth.uid(); photo_id uuid; photo_count integer; next_pos integer; begin if uid is null then raise exception 'authentication required'; end if; if not public.account_is_active(uid) then raise exception 'account_restricted'; end if; if p_storage_path is null or p_storage_path='' or split_part(p_storage_path,'/',1)<>uid::text then raise exception 'invalid photo path'; end if; if not exists(select 1 from storage.objects where bucket_id='profile-photos' and name=p_storage_path) then raise exception 'photo object not found'; end if; select count(*),coalesce(max(position),-1)+1 into photo_count,next_pos from public.profile_photos where user_id=uid; if photo_count>=9 then raise exception 'maximum 9 photos'; end if; insert into public.profile_photos(user_id,storage_path,position,is_primary,moderation_status) values(uid,p_storage_path,next_pos,photo_count=0,'pending') returning id into photo_id; return photo_id; end $$;

create or replace function public.set_my_primary_photo(photo_uuid uuid) returns void language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); begin if uid is null then raise exception 'not authenticated'; end if; if not public.account_is_active(uid) then raise exception 'account_restricted'; end if; if not exists(select 1 from public.profile_photos where id=photo_uuid and user_id=uid) then raise exception 'photo not found'; end if; perform pg_advisory_xact_lock(hashtextextended(uid::text,0)); update public.profile_photos set is_primary=false where user_id=uid and is_primary; update public.profile_photos set is_primary=true where id=photo_uuid and user_id=uid; end $$;

create or replace function public.move_my_profile_photo(photo_uuid uuid, direction integer) returns void language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); curpos smallint; target_id uuid; targetpos smallint; begin if uid is null then raise exception 'not authenticated'; end if; if not public.account_is_active(uid) then raise exception 'account_restricted'; end if; if direction not in (-1,1) then raise exception 'invalid direction'; end if; perform pg_advisory_xact_lock(hashtextextended(uid::text,0)); select position into curpos from public.profile_photos where id=photo_uuid and user_id=uid for update; if curpos is null then raise exception 'photo not found'; end if; if direction=-1 then select id,position into target_id,targetpos from public.profile_photos where user_id=uid and position<curpos order by position desc limit 1 for update; else select id,position into target_id,targetpos from public.profile_photos where user_id=uid and position>curpos order by position asc limit 1 for update; end if; if target_id is null then return; end if; update public.profile_photos set position=-32768 where id=target_id; update public.profile_photos set position=targetpos where id=photo_uuid; update public.profile_photos set position=curpos where id=target_id; end $$;

create or replace function public.update_my_visibility(p_show_age boolean,p_show_distance boolean,p_show_orientation boolean,p_show_gender boolean,p_show_work boolean,p_show_school boolean,p_show_recent_activity boolean,p_discoverable boolean,p_invisible_mode boolean) returns void language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); begin if uid is null then raise exception 'unauthenticated'; end if; if not public.account_is_active(uid) then raise exception 'account_restricted'; end if; insert into public.profile_visibility(user_id,show_age,show_distance,show_orientation,show_gender,show_work,show_school,show_recent_activity,discoverable,invisible_mode,updated_at) values(uid,coalesce(p_show_age,true),coalesce(p_show_distance,true),coalesce(p_show_orientation,false),coalesce(p_show_gender,true),coalesce(p_show_work,true),coalesce(p_show_school,true),coalesce(p_show_recent_activity,true),coalesce(p_discoverable,true),coalesce(p_invisible_mode,false),now()) on conflict(user_id) do update set show_age=excluded.show_age,show_distance=excluded.show_distance,show_orientation=excluded.show_orientation,show_gender=excluded.show_gender,show_work=excluded.show_work,show_school=excluded.show_school,show_recent_activity=excluded.show_recent_activity,discoverable=excluded.discoverable,invisible_mode=excluded.invisible_mode,updated_at=now(); end $$;